INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(5164, 'ptBR', 'Criou o maior problema revirando lixo mágico em Luaprata. Ainda bem que você conseguiu ajudar ele!', '|cFFFFD200Descoberta:|r Luaprata|n', 69497),
(5077, 'ptBR', '', '', 69497);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(318840, 'ptBR', '', 'Os espíritos tiram e os espíritos dão, né? Tenta a sorte de novo na próxima.', 69497),
(317406, 'ptBR', '(grito de agonia)', '', 69497),
(317402, 'ptBR', '(sufocando)', '', 69497),
(317398, 'ptBR', '(respiração arfante)', '', 69497),
(318450, 'ptBR', '', 'Aquele é o nosso alvo.', 69497),
(318448, 'ptBR', '', 'Esconda-se nas trevas, rápido!', 69497),
(314045, 'ptBR', '', 'Não me assuste assim.', 69497),
(314044, 'ptBR', '', 'De volta ao ringue.', 69497),
(314043, 'ptBR', '', 'Se for lutar comigo, tem que continuar lutando.', 69497),
(314042, 'ptBR', '', 'Não ouse morrer aqui comigo!', 69497),
(314010, 'ptBR', '', 'Recuar! Precisamos nos reagrupar.', 69497),
(313727, 'ptBR', '', 'Vou dar cobertura.', 69497),
(313723, 'ptBR', '', 'Mate o inimigo. Me fortaleça!', 69497),
(313717, 'ptBR', '', 'Só existe uma Valira. Derrube o inimigo!', 69497),
(321873, 'ptBR', '', 'Segurar a mão dela.', 69497),
(320494, 'ptBR', '', 'Valeu, $n. Mesmo não tendo salvado elas, essas informações vão salvar vidas.', 69497),
(319326, 'ptBR', 'Um... dois... três...\n\nAh... Oi!\n\nA gente estava brincando de esconde-esconde. Tá todo mundo escondido. Eles não se escondem comigo porque dizem que sou fácil demais de achar...\n\nMas você parece ser muito b$Uom:oa; em procurar! Bem melhor que eu...\n\nQuer procurar eles?\n\nVou logo avisando... eles escolhem esconderijos muito bons.\n\nCinco... seis... sete...', 'Um... dois... três...\n\nAh... Oi!\n\nA gente estava brincando de esconde-esconde. Tá todo mundo escondido. Eles não se escondem comigo porque dizem que sou fácil demais de achar...\n\nMas você parece ser muito b$Uom:oa; em procurar! Bem melhor que eu...\n\nQuer procurar eles?\n\nVou logo avisando... eles escolhem esconderijos muito bons.\n\nCinco... seis... sete...', 69497),
(318831, 'ptBR', 'Ladr$Uão:a;...', '', 69497),
(318533, 'ptBR', '', 'Tudo o que passamos...\n\nNão pode ter sido em vão.', 69497),
(318238, 'ptBR', 'O quê?! Ela matou a aldeia toda? Que tipo de loa...', '', 69497),
(317991, 'ptBR', 'Por favor! Se você não usar essa dádiva, vou ficar presa aqui pra sempre! Te dou o que você quiser! Mas use a dádiva!', '', 69497),
(317886, 'ptBR', 'É muta gentileza sua salvar essa pobre raposa velha! Você me deu uma dádiva, por isso vou devolver o favor em triplo! Três dádivas são suas.\n\nQual é a primeira dádiva que você quer?', '', 69497),
(317371, 'ptBR', 'Meus pais...', '', 69497),
(317362, 'ptBR', 'Concentre-se.', '', 69497),
(316476, 'ptBR', 'Abandonaram o nosso avô, abandonaram nosso tio e vão te abandonar também.', '', 69497),
(316469, 'ptBR', '', 'Por que você tá fazendo isso?', 69497),
(316440, 'ptBR', 'Quando olho pro Caos, sabe o que vejo?', '', 69497),
(315773, 'ptBR', 'GOLAÇO! Um belo lance final pra uma partida de cranibol cheia de ação! Uma partida histórica, meu povo, e que eu não vou esquecer tão cedo.', '', 69497),
(315751, 'ptBR', 'Isso é que é jogar com a cabeça!', '', 69497),
(315736, 'ptBR', 'Senhoras e senhores, chegou a hora de testemunhar, mais uma vez, o jogo dos reis e o rei dos jogos: cranibol!', '', 69497),
(315715, 'ptBR', 'Diz a lenda que o nosso bruxo gastou DOIS estilhaços de alma pra evocar o próximo competidor! É grande, é azul e não gosta desse lugar! É o Guth\'kar!', '', 69497),
(315706, 'ptBR', 'Até um bando maltrapilho de... espera aí, isso é $Uum:uma; $pr e uma elfa sem calça? Até eles!', '', 69497),
(314378, 'ptBR', 'Que a experimentação... comece!', '', 69497),
(313757, 'ptBR', 'Que bom ver gente nova por aqui. Eu e a tripulação naufragamos nessa ilha há mais de sete anos e já estávamos começando a achar que teríamos que reconstruir a sociedade do zero!', '', 69497),
(313655, 'ptBR', 'A peçonha queima fundo. Carne e osso!', '', 69497),
(313623, 'ptBR', '', 'Hehehe. Orweyna? Tu tá falando com Nek\'zali. Ajoelha, que eu te deixo viver.', 69497),
(313438, 'ptBR', '', 'Agora estou entediada de novo.', 69497),
(313337, 'ptBR', 'Suma da minha frente!', '', 69497),
(313292, 'ptBR', 'Tortollanos... Esse fedor de peixe e mar. Pftt! Que nojeira!', '', 69497),
(313265, 'ptBR', 'Um resgate? E por $Uum forasteiro:uma forasteira;, ainda por cima. Estou em dívida com você, $n.', '', 69497),
(313191, 'ptBR', 'Olá! Você tem cara de ser exatamente o tipo de jovem $c íntegr$Uo:a; e corret$Uo:a; que eu estava procurando.\n\nMuitos dos nossos anciãos mais venerados não conseguiram escapar dos saqueadores dendronins quando eles invadiram nosso acampamento.\n\nOs séculos os abençoaram com cascos grossos e memórias afiadas, mas não foram tão generosos no quesito rapidez.\n\nVocê se importaria de ajudar uns cascos velhos a alcançar liberdade?\n\nE, caso se depare com algumas das relíquias e pergaminhos que fomos obrigados a abandonar, eles seriam de grande ajuda para o nosso novo acampamento.', 'Olá! Você tem cara de ser exatamente o tipo de jovem $c íntegr$Uo:a; e corret$Uo:a; que eu estava procurando.\n\nMuitos dos nossos anciãos mais venerados não conseguiram escapar dos saqueadores dendronins quando eles invadiram nosso acampamento.\n\nOs séculos os abençoaram com cascos grossos e memórias afiadas, mas não foram tão generosos no quesito rapidez.\n\nVocê se importaria de ajudar uns cascos velhos a alcançar liberdade?\n\nE, caso se depare com algumas das relíquias e pergaminhos que fomos obrigados a abandonar, eles seriam de grande ajuda para o nosso novo acampamento.', 69497),
(313079, 'ptBR', 'Não! Isso ainda não acabou...', '', 69497),
(312978, 'ptBR', 'Ah! Após milhares de anos, estou livre! Preciso encontrar um novo corpo apropriado.', '', 69497),
(312896, 'ptBR', '', 'Hum... Qual o problema? Dores de cabeça? Maldições? Péssimas decisões? Eu trato tudo isso, e às vezes o tratamento é o mesmo.', 69497),
(312775, 'ptBR', '', 'Huh. Toma cuidado, hash\'ura. Tu tá começando a falar que nem Amani.', 69497),
(312568, 'ptBR', 'Vermelho. Viscoso. <nhac> Delicioso.', '', 69497),
(312407, 'ptBR', '', 'Haha! Então, resolveu voltar.', 69497),
(312364, 'ptBR', '', 'Olha! A porta finalmente tá aberta! Tô indo, Zul\'jan. Aguenta firme...', 69497),
(312317, 'ptBR', 'Tem coisa muito mais assustadora que cobra nessa ilha!', '', 69497),
(312311, 'ptBR', 'Uh... Isso que tu tem aí... chega a reluzir de poder...', '', 69497),
(311954, 'ptBR', '', 'Tu... Ugh... achou o Jan?', 69497),
(311951, 'ptBR', 'Ah! Que fascinante... Uma verdadeira fonte de angústia.', '', 69497),
(311938, 'ptBR', 'Oh, quanta palidez. Será algum vestígio de peçonha?', '', 69497),
(311936, 'ptBR', 'Hmm. A serpente jaz sem presas. Seu domínio permanece.', '', 69497),
(311893, 'ptBR', '', 'Hum. Essa é uma decisão pela qual vale brindar.', 69497),
(311857, 'ptBR', 'Mais uma rodada? Hehe. Você traz os problemas que eu gosto. Eu gosto de você, panda velho.', '', 69497),
(311849, 'ptBR', 'Hehe! Os problemas ainda me encontram, meu amigo, mas a boa bebida também. Geralmente, os dois ao mesmo tempo.', '', 69497),
(311846, 'ptBR', 'Hmm, *GULP*, ah! Só posso dizer que você honra o seu legado. É uma bebida para se apreciar sem pressa.', '', 69497),
(311845, 'ptBR', 'Então... o que achou?', '', 69497),
(311800, 'ptBR', '', '<tosse> Os hash\'ey te dão as boas-vindas.', 69497),
(311779, 'ptBR', '', 'Zerenago, honrado med\'jai. Outros vieram nos substituir na vigília.', 69497),
(311769, 'ptBR', 'Ah, mais uma alma exploradora!', '', 69497),
(311762, 'ptBR', '', 'Tá bem ali. Pode entregar para ele?', 69497),
(311691, 'ptBR', 'A gente respeita os mortos, mas ectoplasma tem utilidade. Pega um pouco dos que forem mais violentos.', '', 69497),
(311583, 'ptBR', '', 'A Prole da Ula\'tek não pode ficar à solta por aí. Matem ela!', 69497),
(311317, 'ptBR', '', 'Argh! Eu tô bem. É só um arranhão. É melhor a gente se reunir na aldeia.', 69497),
(311250, 'ptBR', 'Argh. O sabor não é muito bom... mas as nossas tropas vão gostar de ter fruta fresca.', '', 69497),
(311241, 'ptBR', 'Os espíritos descansaram. Vou fazer um bom proveito das armas deles.', '', 69497),
(310320, 'ptBR', '', 'Eu sei que você quer apaziguar minha preocupação, $n, mas minhas palavras têm um peso de que só me dei conta recentemente. Fui afobada ao querer reconstruir as pontes entre nosso povo segmentado. Agora, os Amani estão pagando o preço.\n\nEu quero consertar essa situação. Quero fazer isso junto.', 69497),
(309826, 'ptBR', '', 'É, já não lembro mais. Olha perto do navio. Vai ver algumas almas ainda perambulam pelo convés.', 69497),
(309825, 'ptBR', '', 'Jelvik? Hum, sim. Ele era feliz. Sempre disposto a ajudar. Tinha um amigo... acho que, hm...', 69497),
(309540, 'ptBR', 'A gente tem que ajudar $Uo:a; $n! Tekkan! Não fica de braços cruzados aí!', '', 69497),
(309165, 'ptBR', 'Heh. Tu ainda confia nos loas? O Zul\'jan agora tem um poder mais forte.', '', 69497),
(309043, 'ptBR', '', 'Nossos inimigos são sempre implacáveis. Aja rápido e acabe com essa ameaça!', 69497),
(308482, 'ptBR', 'Se o Zul\'jan acha que a gente vai deixar ele governar no lugar da Zul\'jarra depois disso, vai aprender uma lição.', '', 69497),
(308324, 'ptBR', '', 'Grande loa da vitória! A hash\'ey dos Amani chama por tua ajuda mais uma vez!', 69497),
(308186, 'ptBR', 'Malacrass deve estar dentro do templo com o Zul\'jan. Os dois são inimigos dos Amani agora.', '', 69497),
(308043, 'ptBR', 'A Lâmina Crepuscular era composta por seguidores de Xal\'atath. Eles ainda devem saber algo a respeito do paradeiro dela.\n\nQuando descobrirmos o que eles sabem, poderemos encontrar Xal\'atath e fazê-la pagar pelo que fez.', '', 69497),
(307747, 'ptBR', '', 'Tu não parece tão forte. Quer mesmo lutar? E tu é $gum:uma; oponente $gdigno:digna;?', 69497),
(307386, 'ptBR', 'Argh... Não sei para onde Xal\'atath foi. Argh... Mas sei que, com Ula\'tek morta, Kith\'ix está livre para se erguer outra vez!', '', 69497),
(307346, 'ptBR', 'É... Antenoriano? Impossível!', '', 69497),
(307324, 'ptBR', 'Para Arator, a nossa vitória na Nascente da Aurora foi transitória. Ele só pensa em achar seus pais... e Xal\'atath.', '', 69497),
(304905, 'ptBR', 'Nek\'zali! Aqui! A gente precisa de cura!', 'Nek\'zali! Aqui! A gente precisa de cura!', 69497),
(304870, 'ptBR', '', 'Um poder maior e mais antigo do que os loas! Com ele, os Amani vão prosperar!', 69497),
(304688, 'ptBR', 'Hahaha! Esse corpo está dançando no meu ritmo!', '', 69497),
(304072, 'ptBR', 'Ninguém vai passar. Ninguém pode ver.', '', 69497),
(303912, 'ptBR', '', 'Hum. Ela deve ter nos trazido aqui por um motivo.', 69497),
(324314, 'ptBR', '', 'E por que não? Eu sou comerciante, então já comprei e vendi mercadorias de todos os povos da Aliança, e para todos eles também. Qualquer coisa bem-feita é digna do meu interesse. E da sua consideração.\n\nSe ajuda, o trator foi feito por um gnomo de Cerro Oeste, não por um humano.', 69497),
(324310, 'ptBR', '', '$UBem-vindo:Bem-vinda;. Ofereço algumas das melhores mercadorias importadas das terras humanas de Cerro Oeste.', 69497),
(317690, 'ptBR', 'Capitão do Nexus Leth\'ir,\n\nA despeito de suas ações, o processamento de mana em Naigtal está superando todas as expectativas.\n\nPortanto, o Autoratum mobilizará agentes de elite para garantir o sucesso da Operação Centelha Arcoceânica.\n\nDossiês dos agentes:\n\n- Lançafeitiços Rem\'lazar, Feitora da Manaforja Oltani\n- Renegado Kulivero, Ex-comandante de Fase\n- Tecnomédica Alazj, Arquitecnomante\n- Guardião Halazir, último modelo de autômato de Alazj\n- Agente de Distorção Xi\'grivr, [informação sigilosa]\n- Artividente Ahl\'syraz, A Arquiteta da Nulidade\n- [Informação sigilosa]\n\nCônsul de Resoluções do Autoratum', 'Capitão do Nexus Leth\'ir,\n\nA despeito de suas ações, o processamento de mana em Naigtal está superando todas as expectativas.\n\nPortanto, o Autoratum mobilizará agentes de elite para garantir o sucesso da Operação Centelha Arcoceânica.\n\nDossiê de agentes:\n\n- Lançafeitiços Rem\'lazar - Feitora da Manaforja Oltani\n- Renegado Kulivero - Ex-comandante de Fase\n- Tecnomédica Alazj - Arquitecnomante\n- Guardião Halazir - Último modelo de autômato de Alazj\n- Agente de Distorção Xi\'grivr - [Informação sigilosa]\n- Artividente Ahl\'syraz - A Arquiteta da Nulidade\n- [Informação sigilosa]\n\n- Cônsul de Resoluções do Autoratum', 69497),
(317689, 'ptBR', 'Capitão do Nexus Leth\'ir,\n\nSuas ações recentes são uma demonstração espantosa de insubordinação e estupidez sem precedentes.\n\nSuas atividades hostis não autorizadas em Azeroth expuseram os Hal\'hadar.\n\nO Autoratum teria motivos para destituí-lo de seu posto e arremessar sua forma desvinculada na estrela heraazi mais próxima.\n\nFelizmente, consegui convencê-lo a se conter.\n\nAgora que as manaforjas de Naigtal estão operacionais, suas ordens são de se retirar de Azeroth e cessar hostilidades.\n\nArcochanceler Ahl\'dynsir', '', 69497),
(317687, 'ptBR', 'Capitão do Nexus Leth\'ir,\n\nA Operação Centelha Arcoceânica é de máxima prioridade para o Autoratum.\n\nOs atrasos no Setor Sodaraam foram associados a ações hostis dos rebeldes mencionados no Registro de Comunicação Beta-J21.\n\nVocê deve aguardar o envio de suprimentos e força de trabalho assim que os portos de carga forem liberados.\n\nCônsul de Resoluções do Autoratum', 'Capitão do Nexus Leth\'ir,\n\nA Operação Centelha Arcoceânica é de máxima prioridade para o Autoratum.\n\nOs atrasos no Setor Sodaraam foram associados a ações hostis dos rebeldes mencionados no Registro de Comunicação Beta-J21.\n\nVocê deve aguardar o envio de suprimentos e força de trabalho assim que os portos de carga forem liberados.\n\n- Cônsul de Resoluções do Autoratum', 69497),
(317686, 'ptBR', 'Cônsul de Resoluções,\n\nEsta é a quarta holomissiva que envio, ainda sem receber resposta.\n\nA entrega de células de mana de Sodaraam ainda não chegou, e minhas forças aguardam a mobilização.\n\nNão é possível estabelecer uma rede inteira de manaforjas, nem mesmo um único duto, sem suprimentos preliminares de mana.\n\nSolicito com urgência o redirecionamento imediato de células de mana de outras redes operacionais.\n\nSeu humilde e paciente servo,\n\nCapitão do Nexus Leth\'ir', 'Cônsul de Resoluções,\n\nEsta é a quarta holomissiva que envio, ainda sem receber resposta.\n\nA entrega de células de mana de Sodaraam ainda não chegou, e minhas forças aguardam a mobilização.\n\nNão é possível estabelecer uma rede inteira de manaforjas, nem mesmo um único duto, sem suprimentos preliminares de mana.\n\nSolicito com urgência o redirecionamento imediato de células de mana de outras redes operacionais.\n\nSeu humilde e paciente servo,\n\nCapitão do Nexus Leth\'ir', 69497),
(317685, 'ptBR', 'Capitão do Nexus Leth\'ir,\n\nVocê foi incumbido da missão de estabelecer uma rede de manaforjas no mundo designado como \"Naigtal\".\n\nOs oceanos deste mundo apresentam altos níveis de energia arcana, o que parece ter afetado os biomas de todo o planeta.\n\nSondagens preliminares com células de mana serão realizadas no mundo com nossa próxima remessa do Setor Sodaraam.\n\nA partir de agora, a Operação Centelha Arcoceânica está em andamento.\n\nCônsul de Resoluções do Autoratum', '', 69497),
(317350, 'ptBR', 'Valeu pela força e por dar um jeito em La\'una.', '', 69497),
(316943, 'ptBR', '', 'Você transformou ele, como transformou o nosso avô!', 69497),
(316933, 'ptBR', 'Os Amani ficaram tão fracos...', '', 69497),
(316473, 'ptBR', 'Um império que amedronta os inimigos. Não um que se humilha a espíritos trapaceiros.', '', 69497),
(315958, 'ptBR', 'Brutal! Esse aí tomou um Gnokaute e tá fora da luta de vez!', '', 69497),
(315957, 'ptBR', 'Mas o quê que é isso? Ele tomou um Gnokaute, mas já tá levantando? Esse aí não fica deitado não!', '', 69497),
(315955, 'ptBR', 'É o macaco craque, o símio magnífico, o grande gorila em pessoa! Gnok!', '', 69497),
(315953, 'ptBR', 'Gnok!', 'Gnok!', 69497),
(315951, 'ptBR', 'Quem é o macacão favorito da plateia?', '', 69497),
(315214, 'ptBR', '', 'Sim.\n\nDesde que você trouxe aquela pedra-chave a Belath, venho esquadrinhando os nossos arquivos em busca de informações.\n\nQuando nos infiltramos em Antorus, nos apoderamos de muita informação acerca de muitos mundos conquistados pela Legião.\n\nClaro que, sem saber de que mundo se origina essa pedra-chave, essas informações podem ser inúteis.', 69497),
(315085, 'ptBR', '', 'Não tenho palavras pra agradecer, $p.\n\nVocê não faz ideia de como curar La\'una e procurar o resto dos batedores era importante pra mim.', 69497),
(315002, 'ptBR', 'Aposto que chego ao fórum antes de você. Até deixo você ir na frente.', '', 69497),
(313066, 'ptBR', 'Todo esse esforço pra nada.', '', 69497),
(313039, 'ptBR', '', 'A barreira está enfraquecendo!', 69497),
(313036, 'ptBR', '', 'Zul\'jarra não tem muito tempo. Vou sondar a área adiante. Derrube as barreiras, $n!', 69497),
(312774, 'ptBR', '', 'O Jan sempre agia como se tivesse um fantasma observando ele. Que precisava dar orgulho pros nossos ancestrais.', 69497),
(311940, 'ptBR', 'Frieza e astúcia até o fim. Impossível não admirar isso. Infelizmente, só um caçador pode prevalecer.', '', 69497),
(311615, 'ptBR', 'Embora ele não domine o Caos, suspeito que sua determinação a encontrar Xal\'atath lhe dê forças para tolerar sua presença, ainda que ele invoque a Luz.', '', 69497),
(311605, 'ptBR', 'Há quem dê a mim — e a todos os elfos caóticos — o rótulo de monstro. Não pretendo enchê-los de razão.', '', 69497),
(310494, 'ptBR', '', 'Ainda lembra do ritmo, não é?', 69497),
(308371, 'ptBR', '', 'Espere. Estou ouvindo... a voz da deusa! Ela está tentando nos contatar...', 69497),
(307753, 'ptBR', 'Agora vamos arrancar minha alma dos ossos. Joga a isca!', '', 69497),
(307646, 'ptBR', '', 'Eu só lembro de querer a glória naquele dia, mas eu esqueci do motivo que me fazia lutar.', 69497),
(307379, 'ptBR', 'De fato. E aposto que Antenoriano sabe como pretendem fazer isso.', '', 69497),
(307367, 'ptBR', 'Argh! Não!', '', 69497),
(305873, 'ptBR', '', 'O Tefokal não corre perigo, mas tenho que tratar dos ferimentos pra não infeccionarem.', 69497),
(304867, 'ptBR', 'Recuar! Leva os feridos pra um abrigo!', '', 69497),
(304624, 'ptBR', '', 'Se aquieta! E fica perto dessa vez.', 69497),
(308552, 'ptBR', 'Ninguém pode adorar ela! Ela tem que ser esquecida!', '', 69497);
