INSERT INTO `currency_types_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(3356, 'ptBR', 'Cristais de Mana Imaculados', 'Podem ser obtidos depois de atingir o Grau 9 da Jornada do Imersor. Podem ser obtidos ao abrir Cofres Abundantes com Chaves de Cofre Restauradas em imersões abundantes de Grau 11 ou superiores. Podem ser trocados com Zah\'ran por equipamentos poderosos.', 69497),
(3418, 'ptBR', 'Núcleo Caótico Nebuloso', 'Pode ser transmutado em um equipamento poderoso ao derrotar inimigos fortes em raides de Midnight ou concluir Masmorras Míticas+, Imersões Abundantes e Caça às Presas no modo Pesadelo. \n\nOs itens podem ser recebidos uma vez por modo até que todos os possíveis itens de sua especialização atual tenham sido transmutados.', 69497),
(3509, 'ptBR', 'Poeira de Centelha de Marés', 'Resíduo mágico obtido com Centelhas de Marés. Usado para acompanhar quantas Centelhas de Marés você já obteve na Série 2 de Midnight.\n\nSe você ficar para trás na obtenção de Centelhas durante a série, concluir conteúdos de nível máximo como Imersões, Míticas+, Raides, JxJ instanciado e alguns eventos de mundo aberto pode ajudar você a recuperar o progresso.', 69497);
